const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let options={},data=null,loading=false,error='',generation=0,scope='',selectedKey='',settingDraft=null,pointDrafts={};
export function weeklyStandingHTML(weekly){if(!weekly)return '';const standing=weekly.standing;return `<section class="card weekly-standing"><div><div class="eyebrow">YOUR DELIVERABLE STANDING</div><strong class="weekly-points">${standing.points}</strong><span> approved points</span><p>${standing.points?`Standing ${standing.rank} of ${standing.classSize} students · Ties share a standing.`:'Your points appear after Teacher Angelo approves your work.'}</p></div><div><span class="pill">${weekly.weekPoints} points this week</span><p>${weekly.completed} of ${weekly.tasks.length} deliverables completed · ${weekly.awaitingApproval} awaiting approval</p><p class="small muted">Points reward completed class work. IELTS practice bands are tracked separately.</p></div></section>`;}
export function studentDeliverablesHTML(state){const head='<div class="page-head"><div class="eyebrow">ONE WEEK. CLEAR NEXT STEPS.</div><h1>This week’s deliverables.</h1><p>Complete your to-do list, submit your work, then receive points after your teacher approves it.</p></div>';if(!state.owner)return head+'<section class="card"><h2>Join your class to see your deliverables.</h2><a class="button" href="#class">Join your class →</a></section>';if(!state.weekly)return head+`<section class="card" role="status">${esc(state.error||'Loading this week’s deliverables…')}</section>`;
 const weekly=state.weekly,pending=weekly.tasks.filter(task=>task.needed),done=weekly.tasks.filter(task=>!task.needed);return head+weeklyStandingHTML(weekly)+`<section class="card weekly-checklist"><div class="section-head"><div><div class="eyebrow">CYCLE ${weekly.window.cycle} · WEEK ${weekly.window.week}</div><h2>${weekly.window.active?'Your to-do list':'Your course starts '+esc(weekly.window.startDate)}</h2><p class="small muted">${esc(weekly.window.startDate)} – ${esc(weekly.window.endDate)} · A new list every week</p></div><button class="button secondary" data-coach-action="refresh-tasks">Refresh</button></div>${weekly.window.active?(!weekly.tasks.length?'<p>Your teacher will share this week’s deliverables here.</p>':pending.length?`<ul>${pending.map(task=>`<li><a class="weekly-task" href="${esc(task.href)}"><span aria-hidden="true">○</span><div><strong>${esc(task.title)}</strong><small>${esc(task.status)}${task.dueDate?' · Due '+esc(task.dueDate):''}</small>${task.message?`<p>${esc(task.message)}</p>`:''}</div><span>Open →</span></a></li>`).join('')}</ul>`:'<p class="notice"><strong>Fantastic job! You’ve finished this week’s deliverables.</strong> '+(weekly.awaitingApproval?'Your teacher will approve your work and award points.':'Your approved points are shown above.')+'</p>'):'<p>Your first reminder will appear when this cycle begins.</p>'}${done.length?`<details><summary>Submitted & approved (${done.length})</summary><ul>${done.map(task=>`<li><a class="weekly-task" href="${esc(task.href)}"><span aria-hidden="true">✓</span><div><strong>${esc(task.title)}</strong><small>${esc(task.status)}${task.approved?' · '+task.points+' points':''}</small></div><span>View →</span></a></li>`).join('')}</ul></details>`:''}<p class="small muted">Speaking homework and mocks need an uploaded recording before teacher approval.</p></section>`;}
function sync(){const session=options.session?.(),next=session?.teacher&&session.connected?'teacher':'';if(next===scope)return;scope=next;generation++;data=null;loading=false;error='';selectedKey='';settingDraft=null;pointDrafts={};}
async function load(force=false){sync();if(!scope||loading||!force&&(data||error))return;const version=generation;loading=true;error='';try{const value=await options.teacherRequest('/api/teacher/weekly'+(selectedKey?'?key='+encodeURIComponent(selectedKey):''));if(version===generation)data=value;}catch(e){if(version===generation)error=e.message;}finally{if(version===generation){loading=false;options.render?.();}}}
export function weeklyConnectionChanged(){sync();}
export function teacherDeliverablesHTML(){sync();if(data&&!selectedKey&&Date.now()>=Date.parse(data.current.endsAt)&&!loading)void load(true);if(!data){if(!error)void load();return `<section class="card"><h2>Weekly deliverables & points</h2><p role="status">${esc(error||'Opening your weekly checklist…')}</p>${error?'<button class="button" data-weekly-action="refresh">Try again</button>':''}</section>`;}
 const setting=settingDraft||data.settings;return `<section class="card"><div class="section-head"><div><h2>Your weekly cycle.</h2><p>One mock and two homework tasks each week. Students see a reminder once each week when they enter the app.</p></div><button class="button secondary" data-weekly-action="refresh" ${loading?'disabled':''}>Refresh</button></div>${error?`<p class="notice warm" role="alert">${esc(error)}</p>`:''}<form id="weeklyCycleForm" class="weekly-settings"><label>Cycle start date<input name="startDate" type="date" required value="${esc(setting.startDate)}"></label><label>Starting lesson week<select name="startWeek">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${setting.startWeek===i+1?'selected':''}>Week ${i+1}</option>`).join('')}</select></label><button class="button">Save weekly cycle</button></form><p class="small muted">The list advances every seven days in UTC+8, then repeats after Week 8. Each new cycle has its own submissions and approvals. Previous approved points stay in the standing.</p></section><section class="card"><div class="section-head"><div><h2>Approve completed deliverables.</h2><p class="small muted">Review the work, choose 0–100 points, then approve it. Saving again updates the award without adding duplicate points.</p></div><label>Deliverable week<select id="weeklyPeriod">${data.periods.map(period=>`<option value="${esc(period.key)}" ${period.key===data.window.key?'selected':''}>Week ${period.week} · ${esc(period.startDate)}</option>`).join('')}</select></label></div><div class="table-wrap"><table><caption>Week ${data.window.week} · ${esc(data.window.startDate)} – ${esc(data.window.endDate)}</caption><thead><tr><th>Student & standing</th><th>Deliverable</th><th>Status</th><th>Review & approve points</th></tr></thead><tbody>${data.students.flatMap(student=>student.tasks.map(task=>{const key=student.id+':'+task.id+':'+data.window.key,points=pointDrafts[key]??(task.approved?task.points:task.suggestedPoints);return `<tr><th>${esc(student.name)}<small>${student.standing.points} points · ${student.standing.points?'Standing '+student.standing.rank:'Awaiting points'}</small></th><td>${esc(task.title)}</td><td><span class="pill">${esc(task.status)}</span>${task.approved?`<p>${task.points} approved points</p>`:''}</td><td>${task.submissionIds.length?`<button class="button secondary" data-weekly-action="review" data-student="${student.id}" data-context="${task.type==='mock'?'weekly-mock':'homework'}">Review work</button>`:''}<form data-weekly-award="${esc(key)}" data-student="${student.id}" data-activity="${esc(task.id)}" class="weekly-award"><label>Points for ${esc(student.name)} · ${esc(task.title)}<input name="points" type="number" min="0" max="100" step="1" required value="${esc(points)}" ${task.complete?'':'disabled'}></label><button class="button soft" ${task.complete&&data.window.started?'':'disabled'}>${task.approved?'Update approved points':'Approve & award points'}</button></form></td></tr>`;})).join('')||'<tr><td colspan="4">Add students to see their weekly deliverables here.</td></tr>'}</tbody></table></div></section>`;}
export function initWeekly(callbacks){options=callbacks;const app=document.querySelector('#app');app.addEventListener('input',event=>{const form=event.target.closest('[data-weekly-award]');if(form)pointDrafts[form.dataset.weeklyAward]=event.target.value;if(event.target.closest('#weeklyCycleForm')){const form=event.target.closest('#weeklyCycleForm');settingDraft={startDate:form.elements.startDate.value,startWeek:Number(form.elements.startWeek.value)};}});app.addEventListener('change',event=>{if(event.target.id==='weeklyPeriod'){selectedKey=event.target.value;data=null;error='';void load(true);options.render?.();}});
 app.addEventListener('click',event=>{const button=event.target.closest('[data-weekly-action]');if(!button)return;if(button.dataset.weeklyAction==='refresh')void load(true);if(button.dataset.weeklyAction==='review')options.openInbox?.(data.window.week,button.dataset.context,button.dataset.student,data.window.key);});
 app.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='weeklyCycleForm'&&!form.dataset.weeklyAward)return;event.preventDefault();if(form.dataset.weeklyBusy)return;form.dataset.weeklyBusy='1';const version=generation,buttons=[...form.querySelectorAll('button')];buttons.forEach(button=>button.disabled=true);try{if(form.id==='weeklyCycleForm'){await options.teacherRequest('/api/teacher/weekly',{method:'PATCH',body:JSON.stringify({startDate:form.elements.startDate.value,startWeek:Number(form.elements.startWeek.value)})});if(version===generation){selectedKey='';settingDraft=null;options.toast?.('Weekly cycle saved.');}}else{await options.teacherRequest('/api/teacher/weekly/approve',{method:'POST',body:JSON.stringify({studentId:form.dataset.student,activityId:form.dataset.activity,windowKey:data.window.key,points:Number(form.elements.points.value)})});if(version===generation){delete pointDrafts[form.dataset.weeklyAward];options.toast?.('Deliverable approved. Points updated.');}}if(version===generation)await load(true);}catch(e){if(version===generation){error=e.message;options.toast?.(e.message);options.render?.();}}finally{delete form.dataset.weeklyBusy;if(version===generation)buttons.forEach(button=>button.disabled=false);}});
}
